"«С данными» — вся база клиентов, заказы, меню, настройки и интервал автосохранения этого компьютера": "«With data» — entire client base, orders, menus, settings, and autosave interval of this computer",
"Каждому курьеру — свой скриншот. «📋 Копировать» → в Telegram Ctrl+V. Все файлы уже сохранены в папке": "Each courier gets their own screenshot. «📋 Copy» → in Telegram Ctrl+V. All files are already saved in the folder",
"Один файл .exe для другого компьютера: внутри программа и всё нужное для работы — на новом компьютере ничего": "One .exe file for another computer: inside is the program and everything needed for work — nothing on the new computer",
"«Для всех» ставится на все калоражи; QR у калоража заменяет общий. QR запоминаются — завтра менять только если он другой": "«For all» applies to all calorie tiers; tier QR replaces the general one. QRs are remembered — tomorrow change only if it's different",
"A5 — положите в принтер картон/бумагу A5; текст сам подстраивается, чтобы всё влезло на лист. При 2 и 4 на A4 — режьте по пунктиру": "A5 — put A5 cardboard/paper in the printer; text adjusts automatically to fit the sheet. For 2 and 4 on A4 — cut along the dotted line",
"Если на том компьютере программа уже есть, её старая база сохранится рядом в папке «data-до-установки». Сборка занимает около минуты": "If the program is already on that computer, its old database will be saved nearby in the «data-before-install» folder. Building takes about a minute",
"дополнительно ставить не надо. Запустите файл там — программа установится, появится ярлык «Ели-Худели» на рабочем столе. Ключ ИИ не переносится — введите его в «Админ» → «ИИ»": "no need to install additionally. Run the file there — the program will install, the «Ели-Худели» shortcut will appear on the desktop. AI key does not transfer — enter it in «Admin» → «AI»",
