"Публикует программу с этого компьютера. Остальные поставят её сами (при запуске и раз в полчаса), база при этом не трогается": "Publishes the program from this computer. Others will install it themselves (at startup and every half hour), the database is untouched",
"Эта версия программы станет у всех: остальные компьютеры поставят её сами при следующей проверке (раз в полчаса или при запуске": "This version of the program will become active for everyone: other computers will install it themselves on the next check (every half hour or at startup",
"Отдать программу: ваши изменения отправятся в облако, и следующий, кто откроет программу, сможет работать. Вы останетесь в режиме просмотра": "Release program: your changes will be sent to the cloud, and the next person to open the program can work. You will remain in view mode",
"Пока он работает, у вас только просмотр. Когда он закроет программу (или его компьютер выключится — через 2–3 минуты), программа сама перейдёт к вам": "While they are working, you only have view mode. When they close the program (or their computer turns off — in 2–3 minutes), the program will automatically pass to you",
