"не нашёл колонки «Название» и «Сумма» или «Цена»": "could not find columns \"Name\" and \"Amount\" or \"Price\"",
"программа покажет, что добавится; дубли пропустит": "program will show what gets added; duplicates will be skipped",
"расход добавляется сам, в свой день; оплатили — ставите галочку": "expense adds itself on its day; paid — check the box",
"if (!nm || /^(итог|всего)/i.test(nm) || /^итог/i.test(String(r[0": "if (!nm || /^(итог|всего)/i.test(nm) || /^итог/i.test(String(r[0",
"больше не будет добавлять расходы. Уже добавленные расходы останутся": "will no longer add expenses. Already added expenses will remain",
"» больше не будет добавлять расходы. Уже добавленные расходы останутся": "» will no longer add expenses. Already added expenses will remain",
"Шаблон: по позиции на каждый приём и напиток — потом всё можно изменить или удалить": "Template: one item per meal and beverage — everything can be changed or deleted later",
"Удалятся все клиенты, заказы, отметки фасовки и меню по дням. Сотрудники, программы, роли, настройки и финансы останутся": "All clients, orders, packing marks, and daily menus will be deleted. Staff, programs, roles, settings, and finances will remain",
"Приёмы пищи берутся из «Меню дня». Здесь — то, что идёт в пакет сверх них. Сколько посуды уходит на каждый пункт, задаётся у позиции инвентаря": "Meals are taken from the \"Daily Menu\". This section covers items going into the pack beyond those. Tableware usage per item is set in inventory settings",
"Считается от пересчёта до пересчёта: было и пришло, минус осталось — столько ушло на деле. «По доставкам» — сколько должно было уйти по числу пакетов": "Calculated from recalculation to recalculation: start plus received, minus remaining equals actual usage. \"By deliveries\" shows how many should have been used based on the number of packs",
"Добавить в настройки «Напиток» (во все форматы меню), если его нет, и по одной позиции «Посуда» на каждый приём и напиток, по 1 штуке? Потом всё можно изменить или удалить": "Add \"Beverage\" to settings (for all menu formats) if missing, and one \"Tableware\" item per meal and beverage, 1 piece each? Everything can be changed or deleted later",
"Разные программы — разный расход: чем больше калораж, тем больше посуды. Правило без отмеченных программ действует для всех остальных. Приём, которого нет в меню клиента, не считается": "Different programs mean different usage: higher calorie count means more tableware. The rule without checked programs applies to all others. Meals absent from a client's menu are not counted",
"Если закончилось раньше времени, при пересчёте укажите, на сколько пакетов хватило: например, заказали 100, по плану на 96 пакетов, закончилось на 88 — пропало 12, до плана не хватило 8": "If it runs out early, specify during recalculation how many packs it lasted: e.g., ordered 100, planned for 96 packs, ran out at 88 — 12 lost, fell short of plan by 8",
