"Клиенты с отдельным меню на эту дату": "Clients with a separate menu for this date",
"Из текста ничего не получилось разложить": "Failed to parse anything from the text",
"Например: когда заканчивается у Каримуллина": "Example: when does Karimullin's plan end",
"Предыдущая часть текста закончилась на дате": "The previous part of the text ended on date",
"ИИ-помощник: вставьте меню, он разложит его сам": "AI assistant: paste the menu, it will sort it itself",
"n, ФИО: c.name, статус: STATUS[inf.status], ...(full": "n, Full Name: c.name, status: STATUS[inf.status], ...(full",
