"Ищет по ФИО, телефону, адресам, комментарию, пометкам и тегам курьеру, аллергенам и примечаниям заказов, программе, курьеру, ответственному. Несколько слов — в любом порядке": "Searches by name, phone, addresses, comment, courier notes and tags, order allergens and notes, program, courier, responsible person. Multiple words — in any order",
"Можно добавлять один день или период «с … по …». Когда компания отдыхает сама (например, на Новый год) — вкладка «Каникулы», там переносятся все клиенты. «(ориент.)» — дата ещё не утверждена, поправьте, когда объявят": "You can add a single day or a period «from ... to ...». When the company rests itself (e.g., New Year) — «Vacation» tab, all clients are transferred there. «(approx.)» — date not approved yet, adjust when announced",
