"Шаблоны граммовок по программам (калорийности": "Portion templates by programs (calories",
"Исключение на конкретный день — в самом меню дня": "Exception for a specific day — in the day menu itself",
"только где отличается от шаблона (серым — шаблон": "only where it differs from the template (gray — template",
