"«Для всех» ставится на все калоражи; QR у калоража заменяет общий. QR запоминаются — завтра менять только если он другой": "«Barchasi uchun» barcha kaloriyalarga qo'yiladi; kaloriyadagi QR umumiyini almashtiradi. QR yodda saqlanadi — ertaga faqat boshqa bo'lsagina o'zgartiring",
"A5 — положите в принтер картон/бумагу A5; текст сам подстраивается, чтобы всё влезло на лист. При 2 и 4 на A4 — режьте по пунктиру": "A5 — printerga A5 karton/qog'oz qo'ying; matn hammasi varaqqa sig'ishi uchun o'zi moslashadi. A4 da 2 va 4 ta bo'lsa — punktir bo'yicha kesing",
"Если на том компьютере программа уже есть, её старая база сохранится рядом в папке «data-до-установки». Сборка занимает около минуты": "Agar o'sha kompyuterda dastur allaqachon mavjud bo'lsa, uning eski bazasi «data-o'rnatishgacha» papkasida saqlanib qoladi. Yig'ish bir daqiqacha vaqt oladi",
"дополнительно ставить не надо. Запустите файл там — программа установится, появится ярлык «Ели-Худели» на рабочем столе. Ключ ИИ не переносится — введите его в «Админ» → «ИИ»": "qo'shimcha o'rnatish shart emas. Faylni o'sha yerda ishga tushiring — dastur o'rnatiladi, ish stolida «Ели-Худели» yorlig'i paydo bo'ladi. SI kaliti ko'chirilmaydi — uni «Admin» → «SI»ga kiriting",
