"Остановлено — клиент в «НЕ ПИТАЕТСЯ», заморожен на неопределённый срок": "To'xtatildi — mijoz «OVQATLANMAYDI», noma'lum muddatga muzlatilgan",
"Адрес страницы меню для QR-кодов (например https://elihudeli.github.io/menu": "QR-kodlar uchun menyu sahifasi manzili (masalan, https://Ели-Худели.github.io/menu",
"у каждого калоража свой QR с блюдами и КБЖУ. Поменяли меню — просто откройте печать бирок заново": "har bir kalorajning o'z taomlari va KBJZU'li QR'i bor. Menyu o'zgardi — birkalar chop etishni qaytadan oching",
"оставшиеся дни сохраняются, клиент переходит в «НЕ ПИТАЕТСЯ» с пометкой «заморожен на неопр. срок»": "qolgan kunlar saqlanadi, mijoz «noma'lum muddatga muzlatilgan» belgisi bilan «OVQATLANMAYDI»ga o'tadi",
"Без промежутков — режьте по пунктиру на резаке: с QR-кодом 10 бирок на листе A4 (2 × 5), без QR — 12 (2 × 6": "Oraliqlarsiz — keskichda shtrix chiziq bo'ylab kesing: QR-kodli A4 varaqda 10 ta birka (2 × 5), QR'siz — 12 ta (2 × 6",
"Страница, которая рисует красивую карточку меню из QR-кода. Файлы для сайта (index.html, menu.html, menu-sw.js": "QR-kodsiz chiroyli menyu kartochkasini chizadigan sahifa. Sayt uchun fayllar (index.html, menu.html, menu-sw.js",
"дополнительно ставить не надо. Запустите файл там — программа установится, появится ярлык «Ели-Худели» на рабочем столе": "qo'shimcha o'rnatish shart emas. Faylni shu yerda ishga tushiring — dastur o'rnatiladi, ish stolida «Ели-Худели» yorlig'i paydo bo'ladi",
"«С ключом ИИ» — на новом компьютере сразу работает подсчёт КБЖУ и проверка аллергий; такой файл не отдавайте посторонним": "«AI kaliti bilan» — yangi kompyuterda KBJZU'ni hisoblash va allergiyalarni tekshirish darhol ishlaydi; bunday faylni begonalarga bermang",
"«С данными» — вся база клиентов, заказы, меню, настройки и интервал автосохранения этого компьютера. «Пустой» — чистая программа без клиентов": "«Ma'lumotlar bilan» — ushbu kompyuterning barcha mijozlar bazasi, buyurtmalar, menyu, sozlamalar va avtosaqlash oralig'i. «Bo'sh» — mijozlarsiz toza dastur",
"Бирки — на все программы (стандарт, Sirtfood, индивидуальные, Fasting…); у стандарта (калории) — QR-код с меню между программой и «Приятного аппетита!»": "Birkalar — barcha dasturlar uchun (standart, Sirtfood, individual, Fasting…); standartda (kaloriyalar) — dastur va «Yoqimli ishtaha!» orasida menyu QR-kodi bor",
"Сейчас при сканировании телефон покажет меню текстом. Чтобы открывалась красивая карточка — укажите адрес страницы меню в «Админ» → «Настройки и установщик»": "Hozir skanerlanganda telefon menyuni matn ko'rinishida ko'rsatadi. Chiroyli kartochka ochilishi uchun — «Admin» → «Sozlamalar va o'rnatuvchi»da menyu sahifasi manzilini ko'rsating",
