"Шаблон: по позиции на каждый приём и напиток — потом всё можно изменить или удалить": "Shablon: har bir qabul va ichimlik uchun bittadan pozitsiya — keyin hammasini o'zgartirish yoki o'chirish mumkin",
"Удалятся все клиенты, заказы, отметки фасовки и меню по дням. Сотрудники, программы, роли, настройки и финансы останутся": "Barcha mijozlar, buyurtmalar, qadoqlash belgilari va kunlik menyular o'chib ketadi. Xodimlar, dasturlar, rollar, sozlamalar va moliya saqlanib qoladi",
"Приёмы пищи берутся из «Меню дня». Здесь — то, что идёт в пакет сверх них. Сколько посуды уходит на каждый пункт, задаётся у позиции инвентаря": "Ovqatlanishlar «Kun menyusi»dan olinadi. Bu yerda — ulardan tashqari paketga tushadigan narsalar. Har bir bandga qancha idish ketishi inventar pozitsiyasida belgilanadi",
"Считается от пересчёта до пересчёта: было и пришло, минус осталось — столько ушло на деле. «По доставкам» — сколько должно было уйти по числу пакетов": "Qayta hisobdan qayta hisobgacha hisoblanadi: bo'lgan va kelgan, qolgani ayiriladi — aslida shuncha ketgan. «Yetkazib berishlar bo'yicha» — paketlar soni bo'yicha qancha ketishi kerak edi",
"Добавить в настройки «Напиток» (во все форматы меню), если его нет, и по одной позиции «Посуда» на каждый приём и напиток, по 1 штуке? Потом всё можно изменить или удалить": "Sozlamalarga «Ichimlik» (barcha menyu formatlariga), agar yo'q bo'lsa, va har bir qabul va ichimlik uchun bittadan «Idish-tovoq» pozitsiyasini, tuman 1 tadan qo'shilsinmi? Keyin hammasini o'zgartirish yoki o'chirish mumkin",
"Разные программы — разный расход: чем больше калораж, тем больше посуды. Правило без отмеченных программ действует для всех остальных. Приём, которого нет в меню клиента, не считается": "Turli dasturlar — turli xarajatlar: kaloraj qancha ko'p bo'lsa, idish-tovoq shuncha ko'p ketadi. Belgilangan dasturlarsiz qoida qolgan barchaga amal qiladi. Mijoz menyusida yo'q qabul hisobga olinmaydi",
"Если закончилось раньше времени, при пересчёте укажите, на сколько пакетов хватило: например, заказали 100, по плану на 96 пакетов, закончилось на 88 — пропало 12, до плана не хватило 8": "Agar vaqtidan oldin tugasa, qayta hisobda nechta paketga yetganini ko'rsating: masalan, 100 ta buyurtma qilindi, 96 ta paket rejasiga ko'ra, 88 taga kelib tugadi — 12 tasi yo'qoldi, rejagacha 8 tasi yetmadi",
