"String(t).toLowerCase().replace(/ё/g": "String(t).toLowerCase().replace(/ё/g",
"Клиенты с отдельным меню на эту дату": "Ushbu sana uchun alohida menyuga ega mijozlar",
"Из текста ничего не получилось разложить": "Matndan hech narsani joylashtirib bo‘lmadi",
"Например: когда заканчивается у Каримуллина": "Masalan: Karimullinda qachon tugaydi",
