"Его клиенты будут получать основное меню": "Оның клиенттері негізгі мәзірді алады",
"С сохранёнными данными и автосохранением": "Сақталған деректермен және автосақтаумен",
"Напоминания «Клиент выбрал дни доставки?»": "«Клиент жеткізілім күндерін таңдады ма?» еске салғыштары",
"Уже оформленные заказы сохранят свои этапы": "Бұрын рәсімделген тапсырыстар өз кезеңдерін сақтап қалады",
"💾 С сохранёнными данными и автосохранением": "💾 Сақталған деректермен және автосақтаумен",
"Не удалось скопировать — возьмите файл из папки": "Көшіру мүмкін емес — файлды папкадан алыңыз",
"Журнал управляющей доступен только в роли «Управляющая»": "Басқарушы журналы тек «Басқарушы» рөлінде ғана қолжетімді",
"Стоит PIN по умолчанию 0000 — смените его внизу страницы": "Әдепкі PIN 0000 тұр — оны беттің төменгі жағында өзгертіңіз",
"убирает из выпадающих списков (старые заказы не меняются": "ашылмалы тізімдерден өшіреді (ескі тапсырыстар өзгермейді",
"скопированный QR / скриншот), перетащите картинку или дважды нажмите — выбрать файл": "көшірілген QR / скриншот), суретті сүйреңіз немесе екі рет басыңыз — файлды таңдау",
"Нажмите и вставьте Ctrl+V, перетащите картинку или дважды нажмите, чтобы выбрать файл": "Басып, Ctrl+V қойыңыз, суретті сүйреңіз немесе файлды таңдау үшін екі рет басыңыз",
"«С данными» — вся база клиентов, заказы, меню, настройки и интервал автосохранения этого компьютера": "«Деректермен» — барлық клиенттер базасы, тапсырыстар, мәзір, баптаулар және осы компьютердің автосақтау аралығы",
"Каждому курьеру — свой скриншот. «📋 Копировать» → в Telegram Ctrl+V. Все файлы уже сохранены в папке": "Әр курьерге — өз скриншоты. «📋 Көшіру» → Telegram-да Ctrl+V. Барлық файлдар папкада сақталып қойған",
"Один файл .exe для другого компьютера: внутри программа и всё нужное для работы — на новом компьютере ничего": "Басқа компьютерге арналған бір .exe файлы: ішінде бағдарлама және жұмысқа қажеттінің бәрі бар — жаңа компьютерде ештеңе",
"«Для всех» ставится на все калоражи; QR у калоража заменяет общий. QR запоминаются — завтра менять только если он другой": "«Барлығы үшін» барлық калораждарға қойылады; калораждағы QR жалпыны алмастырады. QR есте сақталады — ертең тек басқа болса ғана өзгереді",
"A5 — положите в принтер картон/бумагу A5; текст сам подстраивается, чтобы всё влезло на лист. При 2 и 4 на A4 — режьте по пунктиру": "A5 — принтерге A5 картон/қағазын салыңыз; мәтін параққа сыю үшін өзі бейімделеді. A4-те 2 және 4 болғанда — пунктир бойынша кесіңіз",
"Если на том компьютере программа уже есть, её старая база сохранится рядом в папке «data-до-установки». Сборка занимает около минуты": "Егер ол компьютерде бағдарлама бұрыннан бар болса, оның ескі базасы «data-до-установки» папкасының қасында сақталады. Құрастыру шамамен бір минут алады",
"дополнительно ставить не надо. Запустите файл там — программа установится, появится ярлык «Ели-Худели» на рабочем столе. Ключ ИИ не переносится — введите его в «Админ» → «ИИ»": "қосымша қоюдың қажеті жоқ. Онда файлды іске қосыңыз — бағдарлама орнатылады, жұмыс үстелінде «Ели-Худели» жарлығы пайда болады. ЖИ кілті көшірілмейді — оны «Админ» → «ЖИ» бөліміне енгізіңіз",
"Ещё один заказ": "Тағы бір тапсырыс",
