"Сохранить этот заказ и сразу оформить этому же клиенту ещё один заказ (например, после Standart — Sirtfood)": "Осы тапсырысты сақтап, сол клиентке бірден тағы бір тапсырыс рәсімдеу (мысалы, Standart-тан кейін Sirtfood)",
"Сохранить этот заказ и сразу оформить этому же клиенту ещё один заказ (например, после Standart — Sirtfood).": "Осы тапсырысты сақтап, сол клиентке бірден тағы бір тапсырыс рәсімдеу (мысалы, Standart-тан кейін Sirtfood).",
