"Дата начала — на следующий день после окончания предыдущего заказа. Если заказы идут параллельно, поставьте ту же дату, что у первого.": "Басталу күні — алдыңғы тапсырыс аяқталғаннан кейінгі күн. Тапсырыстар қатар жүрсе, біріншісімен бірдей күнді қойыңыз.",
