"Адрес страницы меню для QR убран — в QR будет текст": "QR үшін мәзір бетінің мекенжайы алынып тасталды — QR-да мәтін болады",
"снимите галочку — режим «QR нет»: текст по центру бирки": "белгіні алыңыз — «QR жоқ» режимі: мәтін бирканың ортасында",
"их нужно один раз выложить на сайт (например GitHub Pages": "оларды сайтқа бір рет жүктеу керек (мысалы, GitHub Pages",
"впишите блюда в «Меню дня», иначе на бирке будет пустой квадрат": "«Күн мәзіріне» тағамдарды жазыңыз, әйтпесе биркада бос квадрат болады",
"Остановлено — клиент в «НЕ ПИТАЕТСЯ», заморожен на неопределённый срок": "Тоқтатылды — клиент «ТАМАҚТАНБАЙДЫ» бөлімінде, белгісіз мерзімге мұздатылған",
"Адрес страницы меню для QR-кодов (например https://elihudeli.github.io/menu": "QR кодтарға арналған мәзір бетінің мекенжайы (мысалы, https://Ели-Худели.github.io/menu",
"у каждого калоража свой QR с блюдами и КБЖУ. Поменяли меню — просто откройте печать бирок заново": "әр калораждың өз тағамдары мен КБЖУ бар QR коды бар. Мәзірді өзгерттіңіз бе — биркаларды басып шығаруды қайта ашыңыз",
"оставшиеся дни сохраняются, клиент переходит в «НЕ ПИТАЕТСЯ» с пометкой «заморожен на неопр. срок»": "қалған күндер сақталады, клиент «заморожен на неопр. срок» белгісімен «ТАМАҚТАНБАЙДЫ» күйіне өтеді",
"Без промежутков — режьте по пунктиру на резаке: с QR-кодом 10 бирок на листе A4 (2 × 5), без QR — 12 (2 × 6": "Аралықсыз — кескіштегі нүктелі сызықпен кесіңіз: QR коды бар A4 парағында 10 бирка (2 × 5), QR-сыз — 12 (2 × 6",
"Страница, которая рисует красивую карточку меню из QR-кода. Файлы для сайта (index.html, menu.html, menu-sw.js": "QR кодтан әдемі мәзір карточкасын салатын бет. Сайтқа арналған файлдар (index.html, menu.html, menu-sw.js",
"дополнительно ставить не надо. Запустите файл там — программа установится, появится ярлык «Ели-Худели» на рабочем столе": "қосымша орнату қажет емес. Сол жерден файлды іске қосыңыз — бағдарлама орнатылады, жұмыс үстелінде «Ели-Худели» жарлығы пайда болады",
"«С ключом ИИ» — на новом компьютере сразу работает подсчёт КБЖУ и проверка аллергий; такой файл не отдавайте посторонним": "«ЖИ кілті бар» — жаңа компьютерде КБЖУ есептеу және аллергияны тексеру бірден жұмыс істейді; мұндай файлды бөгде адамдарға бермеңіз",
"«С данными» — вся база клиентов, заказы, меню, настройки и интервал автосохранения этого компьютера. «Пустой» — чистая программа без клиентов": "«Деректері бар» — барлық клиенттер базасы, тапсырыстар, мәзіr, параметрлер және осы компьютердің автоматты түрде сақтау аралығы. «Бос» — клиенттері жоқ таза бағдарлама",
"Бирки — на все программы (стандарт, Sirtfood, индивидуальные, Fasting…); у стандарта (калории) — QR-код с меню между программой и «Приятного аппетита!»": "Биркалар — барлық бағдарламалар үшін (стандарт, Sirtfood, жеке, Fasting…); стандартта (калория) — бағдарлама мен «Приятного аппетита!» арасында мәзірі бар QR-код",
"Сейчас при сканировании телефон покажет меню текстом. Чтобы открывалась красивая карточка — укажите адрес страницы меню в «Админ» → «Настройки и установщик»": "Қазір скан жасағанда телефон мәзірді мәтін ретінде көрсетеді. Әдемі карточка ашылуы үшін — «Админ» → «Настройки и установщик» бөлімінде мәзір бетінің мекенжайын көрсетіңіз",
