"больше не будет добавлять расходы. Уже добавленные расходы останутся": "бұдан былай шығыстарды қоспайды. Бұрын қосылған шығыстар қалады",
"» больше не будет добавлять расходы. Уже добавленные расходы останутся": "» бұдан былай шығыстарды қоспайды. Бұрын қосылған шығыстар қалады",
"Шаблон: по позиции на каждый приём и напиток — потом всё можно изменить или удалить": "Үлгі: әр тамақ пен сусынға бір позициядан — кейін бәрін өзгертуге немесе жоюға болады",
"Удалятся все клиенты, заказы, отметки фасовки и меню по дням. Сотрудники, программы, роли, настройки и финансы останутся": "Барлық клиенттер, тапсырыстар, фасовка белгілері және күндізгі мәзір жойылады. Қызметкерлер, бағдарламалар, рөлдер, баптаулар және қаржы қалады",
"Приёмы пищи берутся из «Меню дня». Здесь — то, что идёт в пакет сверх них. Сколько посуды уходит на каждый пункт, задаётся у позиции инвентаря": "Тағамдар «Күн мәзірінен» алынады. Мұнда — олардан тыс пакетке түсетіндер. Әр тармаққа қанша ыдыс кететіні инвентарь позициясында көрсетіледі",
"Считается от пересчёта до пересчёта: было и пришло, минус осталось — столько ушло на деле. «По доставкам» — сколько должно было уйти по числу пакетов": "Қайта есептеуден қайта есептеуге дейін есептеледі: болды және келді, қалғанын шегергенде — іс жүзінде сонша кетті. «Жеткізулер бойынша» — пакет саны бойынша қанша кетуі керек еді",
"Добавить в настройки «Напиток» (во все форматы меню), если его нет, и по одной позиции «Посуда» на каждый приём и напиток, по 1 штуке? Потом всё можно изменить или удалить": "Мәзірдің барлық форматтарында жоқ болса, баптауларға «Сусын» қосу, және әр тағам мен сусынға бір позициядан «Ыдыс», әрқайсысы 1 данадан? Кейін бәрін өзгертуге немесе жоюға болады",
"Разные программы — разный расход: чем больше калораж, тем больше посуды. Правило без отмеченных программ действует для всех остальных. Приём, которого нет в меню клиента, не считается": "Әртүрлі бағдарламалар — әртүрлі шығыс: калориясы жоғары болған сайын, ыдыс көп кетеді. Белгіленген бағдарламалары жоқ ереже барлық басқаларға қолданылады. Клиент мәзірінде жоқ тағам есептелмейді",
"Если закончилось раньше времени, при пересчёте укажите, на сколько пакетов хватило: например, заказали 100, по плану на 96 пакетов, закончилось на 88 — пропало 12, до плана не хватило 8": "Мезгілінен бұрын бітіп қалса, қайта есептеу кезінде қанша пакетке жеткенін көрсетіңіз: мысалы, 100 тапсырыс берілді, 96 пакетке жоспарланған, 88-де бітті — 12 жоғалды, жоспарға 8 жетпеді",
