"Курьеры без заказов больше месяца — из старой истории": "Бір айдан артық тапсырысы жоқ курьерлер — ескі тарихтан",
"только этот клиент; без галочки — все клиенты курьера": "тек бұл клиент; белгісіз — курьердің барлық клиенттері",
"Показать только этого курьера (можно выбрать нескольких": "Тек осы курьерді көрсету (бірнешеуін таңдауға болады",
"ИИ посчитает КБЖУ только этому клиенту и заменит его значения": "ЖИ тек осы клиент үшін БЖҚС есептеп, оның мәндерін алмастырады",
"Обновите перед работой — это несколько секунд, все данные сохранятся": "Жұмыс алдында жаңартыңыз — бұл бірнеше секунд, барлық деректер сақталады",
"для каждого клиента этого меню, по порядку фасовки — положите в пакет этого клиента": "осы мәзірдің әрбір клиенті үшін, фасовка ретімен — осы клиенттің пакетіне салыңыз",
"Номера сквозные — напишите номер на пакете; карточки меню печатаются в этом же порядке": "Нөмірлер реттік — нөмірді пакетке жазыңыз; мәзір карточкалары сол ретпен басып шығарылады",
"На эти даты в доставке, у курьеров и в «Мои доставки» будет этот адрес, потом снова основной": "Бұл күндері жеткізуде, курьерлерде және «Менің жеткізулерім» бөлімінде осы мекенжай болады, содан кейін қайтадан негізгі",
"Адрес на период действует сам. Адрес по графику программа не подставляет — в «Доставке» появится подсказка «Применить на …»": "Кезеңге арналған мекенжай өзі әрекет етеді. Кесте бойынша мекенжайды бағдарлама өзі қоймайды — «Жеткізуде» «… қолдану» кеңесі пайда болады",
"Например: в будни — работа, в выходные — дом. Программа сама адрес не меняет: в «Доставке» появится подсказка, старший курьер применит её на нужный день": "Мысалы: жұмыс күндері — жұмыс, демалыста — үй. Бағдарлама мекенжайды өзі өзгертпейді: «Жеткізуде» кеңес пайда болады, аға курьер оны қажетті күнге қолданады",
"A5 — положите в принтер картон/бумагу A5 и в окне печати выберите размер бумаги A5; текст сам подстраивается, чтобы всё влезло на лист. При 2 и 4 на A4 — режьте по пунктиру": "A5 — принтерге A5 картон/қағазын салып, басып шығару терезесінде A5 қағаз өлшемін таңдаңыз; мәтіннің бәрі параққа сыюы үшін өзі бейімделеді. A4-те 2 және 4 болғанда — нүктелі сызық бойынша кесіңіз",
"Постоянный курьер в заказе остаётся. В выбранные дни доставку, курьерскую базу, скриншоты и «Мои доставки» получает временный курьер, в «Доставке» у клиента пометка «временный курьер»": "Тапсырыстағы тұрақты курьер қалады. Таңдалған күндері жеткізуді, курьерлік базаны, скриншоттарды және «Менің жеткізулерім» бөлімін уақытша курьер алады, «Жеткізуде» клиентте «уақытша курьер» белгісі тұрады",
